// Local provider for demo requests. Responses are generated by fixed rules.
const http = require('node:http');
const normalize = value => value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');

function answer(messages) {
    const instructions = messages[0]?.content || '';
    const input = messages[1]?.content || '';
    if (instructions.includes('Extract event search filters')) {
        const query = normalize(input.split('User request:')[1] || input);
        const keyword = ['ha noi','hai phong','nam dinh','song lam nghe an','binh duong','da nang']
            .find(team => query.includes(team));
        const teams = {'ha noi':'Hà Nội','hai phong':'Hải Phòng','nam dinh':'Nam Định',
            'song lam nghe an':'Sông Lam Nghệ An','binh duong':'Bình Dương','da nang':'Đà Nẵng'};
        const price = query.match(/(?:duoi|toi da)\s*([\d.,]+)\s*(k|nghin|ngan)?/);
        const category = /\b(phim|rap|suat chieu)\b/.test(query) ? 'CINEMA'
            : /\b(nhac|concert)\b/.test(query) ? 'MUSIC'
            : keyword || /\b(bong da|tran)\b/.test(query) ? 'SPORTS' : null;
        const title = query.includes('chuyen tau mua dong') ? 'Chuyến tàu mùa đông'
            : query.includes('dem nhac thang muoi hai') ? 'Đêm nhạc Tháng Mười Hai' : null;
        return {category,keyword:teams[keyword] || title,venue:null,from:null,to:null,
            maxPrice:price ? Number(price[1].replace(/[.,]/g,'')) * (price[2] ? 1000 : 1) : null};
    }
    const {question, event} = JSON.parse(input);
    const query = normalize(question);
    const description = event.description || '';
    const term = query.includes('gui xe') ? 'giu xe' :
        query.includes('tre em') ? 'tre em' : query.includes('mo cua') ? 'mo cua' : '';
    const sentence = term && description.split(/(?<=[.!?])\s+/).find(line => normalize(line).includes(term));
    return {answer:sentence || 'Thông tin này chưa được cung cấp trong mô tả sự kiện.'};
}

const server = http.createServer(async (req, res) => {
    if (req.url === '/health') { res.writeHead(200); return res.end('Demo provider ready'); }
    if (req.method !== 'POST' || req.url !== '/v1/chat/completions') {
        res.writeHead(404); return res.end();
    }
    try {
        let body = '';
        for await (const chunk of req) {
            body += chunk;
            if (body.length > 100000) throw new Error('Body too large');
        }
        const content = JSON.stringify(answer(JSON.parse(body).messages));
        res.writeHead(200, {'Content-Type':'application/json; charset=utf-8'});
        res.end(JSON.stringify({choices:[{finish_reason:'stop',message:{content}}]}));
    } catch {
        res.writeHead(400); res.end('{}');
    }
});
const port = Number(process.argv[2] || 18089);
server.on('error', () => { console.error('Cannot open demo AI port ' + port); process.exitCode=1; });
server.listen(port,'127.0.0.1',()=>console.log('Local demo AI ready on port ' + port));
